  sheet.getRange('L5:N7').setBackground('#FFF5F5').setBorder(true, true, true, true, false, false, '#FED7D7', SpreadsheetApp.BorderStyle.SOLID);

  // 4. Head-to-Head Scenario Spotlight Table (Rows 9-13)
